// WRITE
const outDir = __dirname;
let count = 0;
for (const [content] of seeders) {
  if (!content) continue;
  const m = content.match(/seed-(\S+?)\.mjs/);
  if (!m) continue;
  const fp = resolve(outDir, m[0]);
  writeFileSync(fp, content, 'utf8');
  count++;
}
console.log(`✅ Written ${count} seeder files to ${outDir}`);